const std::array<Parameter, kParameterCount>& parameters() { return kParameters; }
const Parameter* parameter(unsigned index) { return index < kParameters.size() ? &kParameters[index] : nullptr; }
const Parameter* parameterForField(int field, bool synced) {
    for (const auto& p : kParameters)
        if (p.field == field && ((p.codec == Codec::Sync || p.codec == Codec::SyncT4) == synced || p.pair < 0)) return &p;
    return nullptr;
}
bool canonicalize(const Parameter& p, double input, int& output) {
    if (!std::isfinite(input)) return false;
    input = std::max(double(p.minimum), std::min(double(p.maximum), input));
    output = p.kind == Kind::Boolean ? (input > (p.minimum + p.maximum) * 0.5 ? p.maximum : p.minimum) : int(std::round(input));
    return true;
}
int read(const Parameter& p, const Program& program) {
    int v = getParam(program, p.field);
    if (p.label == LabelKind::LfoPhase || p.label == LabelKind::EnvVelLevel || p.label == LabelKind::EnvT4) v &= 127;
    if (p.codec == Codec::Voices && v == 0) v = 8;
    if (p.codec == Codec::SyncT4) v = std::min(v & 63,35) + ((v & 64) ? 36 : 0);
    return std::max(p.minimum, std::min(p.maximum, v));
}
bool write(const Parameter& p, Program& program, double value) {
    int v;
    if (!canonicalize(p,value,v)) return false;
    if (p.codec == Codec::SyncT4 && v >= 36) v = (v - 36) | 64;
    if (p.label == LabelKind::LfoPhase || p.label == LabelKind::EnvVelLevel || p.label == LabelKind::EnvT4 || p.codec == Codec::SyncT4) {
        const auto off = ofs::Body + paramTable()[size_t(p.field)].offset;
        program.setBits(off,0,7,unsigned(v));
    } else setParam(program,p.field,v);
    return true;
}
double normalize(const Parameter& p, int value) { return double(value-p.minimum)/double(p.maximum-p.minimum); }
std::string choiceLabel(const Parameter& p, int value) {
    if (value < p.minimum || value > p.maximum) return {};
    if (p.label == LabelKind::OffOn) return value > 0 ? "ON" : "OFF";
    if (p.label == LabelKind::Unsigned || p.label == LabelKind::Signed || p.label == LabelKind::None) return std::to_string(value);
    return labels::format(p.label,value);
}
